{
  "root_causes": [
    {
      "service": "ts-station-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-station-service' AND span_name='SELECT station' GROUP BY 1,2,3", "claim": "Station's own 'SELECT station' DB spans error out after about 30s, averaging 30001 ms in the abnormal window."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-station-service' AND level='ERROR' GROUP BY 1,2,3", "claim": "Station logs HikariPool connection timeouts and MySQL 'Communications link failure' / SQLState 08S01 errors."},
        {"kind": "metric", "sql": "SELECT 'abn' p, metric, attr_k8s_pod_name, round(avg(value),3) avg_v FROM abnormal_metrics WHERE service_name='ts-station-service' AND metric='container.cpu.usage' GROUP BY 1,2,3 UNION ALL SELECT 'norm', metric, attr_k8s_pod_name, round(avg(value),3) FROM normal_metrics WHERE service_name='ts-station-service' AND metric='container.cpu.usage' GROUP BY 1,2,3", "claim": "Station CPU fell from about 0.04 to 0.01 while its DB calls hung, so the pod sat idle waiting on the database."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-station-service", "to": "ts-basic-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name LIKE 'POST%' GROUP BY 1,2,3", "claim": "Basic's travels endpoint errors at about 30s, with 403s from its station call."}]},
    {"from": "ts-station-service", "to": "ts-admin-basic-info-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name LIKE 'GET%' GROUP BY 1,2,3", "claim": "Admin basic-info stations call hits about 30s and errors when station is down."}]},
    {"from": "ts-basic-service", "to": "ts-travel-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name LIKE '%trips%' GROUP BY 1,2,3", "claim": "Travel's trips/left endpoint errors and slows to about 28 s as its basic-service calls time out."}]},
    {"from": "ts-travel-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name LIKE '%/%' GROUP BY 1,2,3", "claim": "Travel-plan cheapest and quickest endpoints error or take about 30 s during the incident."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE 'GET%' OR span_name LIKE 'POST%' GROUP BY 1,2,3", "claim": "User-facing dashboard requests to travel-plan endpoints slow to about 20-30 s."}]}
  ]
}
